(16664,20,'Proverbs','OT',10,7,'Ang handumanan sang matarung bulahan,'),
(16665,20,'Proverbs','OT',10,8,'Ang maalam sa tagiposoon magabaton sang mga sogo,'),
(16666,20,'Proverbs','OT',10,9,'Ang nagalakat sing matadlong nagalakat sing malig-on,'),
(16667,20,'Proverbs','OT',10,10,'Ang nagapangilay nagapasubo,'),
