(16677,20,'Proverbs','OT',10,20,'Ang dila sang matarung subong sang pinili nga pilak;'),
(16678,20,'Proverbs','OT',10,21,'Ang mga bibig sang matarung nagapakaon sing madamu,'),
(16679,20,'Proverbs','OT',10,22,'Ang pagpakamaayo sang Ginoo nagapamanggad,'),
(16680,20,'Proverbs','OT',10,23,'Subong sang hampang sa buangbuang ang paghimo sing pagkamalaut,'),
