(16684,20,'Proverbs','OT',10,27,'Ang kahadluk sa Ginoo nagapalawig sang mga adlaw,'),
(16685,20,'Proverbs','OT',10,28,'Ang paglaum sang mga matarung kasadyahan,'),
(16686,20,'Proverbs','OT',10,29,'Ang dalanon sang Ginoo pamakud sa matadlong,'),
(16687,20,'Proverbs','OT',10,30,'Ang matarung indi mationg,'),
