(17007,20,'Proverbs','OT',21,22,'Ang maalam nga tawo nagataklas sang banwa sang gamhanan'),
(17008,20,'Proverbs','OT',21,23,'Ang bisan sin-o nga nagabantay sang iya baba kag sang iya dila'),
(17009,20,'Proverbs','OT',21,24,'Ang bugalon kag palabilabihon nga tawo, “Mayubiton” amo ang iya ngalan'),
(17010,20,'Proverbs','OT',21,25,'Ang handum sang matamad nagapatay sa iya'),
(17011,20,'Proverbs','OT',21,26,'May dira nga nagahamkon sing hinakog sa bug-os nga adlaw,'),
(17012,20,'Proverbs','OT',21,27,'Ang halad sang malauton kangil-aran;'),
(17013,20,'Proverbs','OT',21,28,'Ang saksi nga dimatuud mawala,'),
(17014,20,'Proverbs','OT',21,29,'Ang tawo nga malaut nagapadamul sang iya nawung,'),
(17015,20,'Proverbs','OT',21,30,'Walay kaalam, ukon paghangup, ukon laygay,'),
(17016,20,'Proverbs','OT',21,31,'Ang kabayo nahanda sa adlaw sang inaway,'),
(17017,20,'Proverbs','OT',22,1,'Ang maayong ngalan pasulabihon sa pagpili sang sa dakung manggad,'),
(17018,20,'Proverbs','OT',22,2,'Ang manggaranon kag ang imol nagakitaay;'),
(17019,20,'Proverbs','OT',22,3,'Ang mahalongon nga tawo nakakita sang malaut kag nagapanago sia;'),
(17020,20,'Proverbs','OT',22,4,'Ang balus sang pagpaubus kag sang kahadluk sa Ginoo'),
(17021,20,'Proverbs','OT',22,5,'Mga tunuk kag mga siod yara sa dalan sang balingag;'),
(17022,20,'Proverbs','OT',22,6,'Hanasa ang bata sa dalanon nga dapat niya paglaktan,'),
(17023,20,'Proverbs','OT',22,7,'Ang manggaranon nagagahum sa imol,'),
(17024,20,'Proverbs','OT',22,8,'Ang nagasab-ug sing kalautan magaani sing kalalat-an,'),
(17025,20,'Proverbs','OT',22,9,'Ang may mata nga maalwan pakamaayohon,'),
(17026,20,'Proverbs','OT',22,10,'Taboga ang mayubiton, kag ang kasuayon magagowa,'),
(17027,20,'Proverbs','OT',22,11,'Ang nagahigugma sang pagkaputli sang tagiposoon,'),
(17028,20,'Proverbs','OT',22,12,'Ang mga mata sang Ginoo nagatipig sang may ihibalo,'),
(17029,20,'Proverbs','OT',22,13,'Ang matamad nagasiling, “May leon sa gowa!'),
(17030,20,'Proverbs','OT',22,14,'Ang baba sang mga babayi nga makihilawason boho nga madalum;'),
(17031,20,'Proverbs','OT',22,15,'Ang kabuangan naputus sa tagiposoon sang bata,'),
(17032,20,'Proverbs','OT',22,16,'Ang nagapigus sang imol sa pagdugang sang iya daug,'),
(17033,20,'Proverbs','OT',22,17,'Ilingig ang imo idulungug, kag pamatii ang mga polong sang maalam,'),
(17034,20,'Proverbs','OT',22,18,'kay maayo nga butang ini kon tipigan mo sila sa sulud mo,'),
(17035,20,'Proverbs','OT',22,19,'Agud nga ang imo pagsalig manginsa Ginoo,'),
(17036,20,'Proverbs','OT',22,20,'Wala bala ako magsulat sa imo sang maayong mga butang'),
(17037,20,'Proverbs','OT',22,21,'sa pagpakilala sa imo sang kalig-onan sang mga polong sang kamatooran,'),
(17038,20,'Proverbs','OT',22,22,'Dili pagkawati ang imol, bangud nga imol sia,'),
(17039,20,'Proverbs','OT',22,23,'kay ang Ginoo magaapin sang kasuayon nila'),
(17040,20,'Proverbs','OT',22,24,'Dili ka makig-abyan sa tawong maakigon,'),
(17041,20,'Proverbs','OT',22,25,'basi nga makatoon ka sang iya mga dalanon'),
(17042,20,'Proverbs','OT',22,26,'Dili ka magmangin-isa sa ila nga nagadagpianay sing mga kamut,'),
(17043,20,'Proverbs','OT',22,27,'Kon wala ka sing ibayad,'),
(17044,20,'Proverbs','OT',22,28,'Dili paghalina ang dumaan nga dulunan'),
(17045,20,'Proverbs','OT',22,29,'Nakakita ka bala sing tawo nga maukud sa iya buluhaton?'),
(17046,20,'Proverbs','OT',23,1,'Kon nagalingkod ka sa pagkaon upud sa manuggahum,'),
(17047,20,'Proverbs','OT',23,2,'kag butangi sing sundang ang imo totonlan'),
(17048,20,'Proverbs','OT',23,3,'Dili mo pagkaibogan ang iya manamit nga mga pagkaon,'),
(17049,20,'Proverbs','OT',23,4,'Dili ka maghimud-os nga magmanggaranon;'),
(17050,20,'Proverbs','OT',23,5,'Ituhoy mo bala ang imo mga mata sa sina nga indi amo?'),
(17051,20,'Proverbs','OT',23,6,'Dili ka magkaon sang kalan-on sang may mata nga malaut;'),
(17052,20,'Proverbs','OT',23,7,'kay sono sa iya ginahunahuna sa sulud niya amo sia.'),
(17053,20,'Proverbs','OT',23,8,'Ang hungit nga nakaon mo isuka mo,'),
(17054,20,'Proverbs','OT',23,9,'Dili ka magpamolong sa palamatin-an sang buangbuang,'),
(17055,20,'Proverbs','OT',23,10,'Dili paghalina ang dumaan nga dulunan'),
(17056,20,'Proverbs','OT',23,11,'kay ang ila Manunubus makusug;'),
(17057,20,'Proverbs','OT',23,12,'Ituhoy ang imo tagiposoon sa pagtudlo'),
(17058,20,'Proverbs','OT',23,13,'Dili pag-idumili ang pagtudlo sa bata;'),
(17059,20,'Proverbs','OT',23,14,'Bunalon mo sia sang bilogon'),
(17060,20,'Proverbs','OT',23,15,'Anak ko, kon ang imo tagiposoon magmaalam,'),
(17061,20,'Proverbs','OT',23,16,'Ang akon tagiposoon magakalipay'),
(17062,20,'Proverbs','OT',23,17,'Dili magkahisa ang imo tagiposoon sa mga makasasala,'),
(17063,20,'Proverbs','OT',23,18,'Kay sa pagkamatuud may balus,'),
(17064,20,'Proverbs','OT',23,19,'Pamati ka, anak ko, kag magmaalam,'),
(17065,20,'Proverbs','OT',23,20,'Dili ka magsimpon sa mga palainum sing alak,'),
(17066,20,'Proverbs','OT',23,21,'kay ang palahobog kag ang hakugan magaimol,'),
(17067,20,'Proverbs','OT',23,22,'Pamatii ang imo amay nga nagpakatawo sa imo,'),
(17068,20,'Proverbs','OT',23,23,'Bakla ang kamatooran, kag dili pag-ibaligya;'),
(17069,20,'Proverbs','OT',23,24,'Ang amay sang matarung magakalipay sing daku;'),
(17070,20,'Proverbs','OT',23,25,'Magkasadya ang imo amay kag ang imo iloy,'),
(17071,20,'Proverbs','OT',23,26,'Anak ko, ihatag sa akon ang imo tagiposoon,'),
(17072,20,'Proverbs','OT',23,27,'Kay ang makihilawason nga babayi madalum nga boho;'),
(17073,20,'Proverbs','OT',23,28,'Nagapuut sia subong sang makawat'),
(17074,20,'Proverbs','OT',23,29,'Sin-o bala ang may pagkakailo? Sin-o bala ang may kasubo?'),
(17075,20,'Proverbs','OT',23,30,'Ang mga nagapabilin sing madugay sa alak,'),
(17076,20,'Proverbs','OT',23,31,'Dili ka magtolok sa alak kon mapula ini,'),
(17077,20,'Proverbs','OT',23,32,'Sa katapusan nagakagat ini kaangay sang man-ug,'),
(17078,20,'Proverbs','OT',23,33,'Ang imo mga mata makakita sing makatilingala nga mga butang,'),
(17079,20,'Proverbs','OT',23,34,'Manginsubong ka sang nagahigda sa tunga sang dagat,'),
(17080,20,'Proverbs','OT',23,35,'“Ginsakit nila ako,” magasiling ka, “kag wala ako masamad;'),
(17081,20,'Proverbs','OT',24,1,'Dili ka magkahisa batok sa mga tawo nga malaut,'),
(17082,20,'Proverbs','OT',24,2,'kay ang ila tagiposoon nagatoon sa pagpigus,'),
(17083,20,'Proverbs','OT',24,3,'Paagi sa kaalam ginapatindug ang balay,'),
(17084,20,'Proverbs','OT',24,4,'paagi sa ihibalo ginapuno ang mga hulut'),
(17085,20,'Proverbs','OT',24,5,'Ang tawo nga maalam makusug,'),
(17086,20,'Proverbs','OT',24,6,'kay sa maalam nga pagtuytuy magapakig-away ka,'),
(17087,20,'Proverbs','OT',24,7,'Ang kaalam tama kataas tungud sa buangbuang;'),
(17088,20,'Proverbs','OT',24,8,'Ang nagapahito sa paghimo sing malaut'),
(17089,20,'Proverbs','OT',24,9,'Ang painoino sang kabuangan sala,'),
(17090,20,'Proverbs','OT',24,10,'Kon mapunaw ka sa adlaw sang kapiotan,'),
(17091,20,'Proverbs','OT',24,11,'Luwasa ang mga ginadala sa kamatayon;'),
(17092,20,'Proverbs','OT',24,12,'Kon magsiling ka, “Yari karon, wala kami makahibalo sini,”'),
(17093,20,'Proverbs','OT',24,13,'Anak ko, kaon ka sing dugus, kay ini maayo,'),
(17094,20,'Proverbs','OT',24,14,'Sa amo makilala mo ang kaalam sa imo kalag;'),
(17095,20,'Proverbs','OT',24,15,'Dili pagput-i, O malaut nga tawo, ang puluy-an sang matarung;'),
(17096,20,'Proverbs','OT',24,16,'kay ang matarung nga tawo mapukan sing makapito, kag nagabangon liwat;'),
(17097,20,'Proverbs','OT',24,17,'Dili ka magkalipay kon mapukan ang imo kaaway,'),
(17098,20,'Proverbs','OT',24,18,'basi nga makita ini sang Ginoo, kag indi magpahamuut sa iya,'),
(17099,20,'Proverbs','OT',24,19,'Dili ka magkaakig bangud sang mga manughimo sang malaut,'),
(17100,20,'Proverbs','OT',24,20,'kay walay balus sa malaut nga tawo;'),
(17101,20,'Proverbs','OT',24,21,'Anak ko, kahadlukan mo ang Ginoo kag ang hari,'),
(17102,20,'Proverbs','OT',24,22,'kay ang ila kalalat-an magatuhaw sing hinali,'),
(17103,20,'Proverbs','OT',24,23,'Ini sila man amo ang mga polong sang maalam.'),
(17104,20,'Proverbs','OT',24,24,'Ang nagasiling sa malauton, “Matarung ka,”'),
(17105,20,'Proverbs','OT',24,25,'apang sa mga nagasabdong sa malauton may kalipay,'),
(17106,20,'Proverbs','OT',24,26,'Nagahaluk sang mga bibig'),
(17107,20,'Proverbs','OT',24,27,'Amana ang imo buluhaton sa luwas,'),
(17108,20,'Proverbs','OT',24,28,'Dili ka magsaksi sa walay kabangdanan batok sa imo isigkatawo,'),
(17109,20,'Proverbs','OT',24,29,'Dili ka magsiling, “Himoon ko sa iya ang subong sang ginhimo niya sa akon;'),
(17110,20,'Proverbs','OT',24,30,'Naglabay ako sa uma sang matamad,'),
(17111,20,'Proverbs','OT',24,31,'yari karon, natuboan ini tanan sang mga tunukon;'),
(17112,20,'Proverbs','OT',24,32,'Niyan gintan-aw ko kag ginpatugsilingan sing maayo;'),
(17113,20,'Proverbs','OT',24,33,'“Diotay pa nga katologon, diotay nga katuyo,'),
(17114,20,'Proverbs','OT',24,34,'sa amo magaabut ang imo kaimolan subong sang buyong,'),
(17115,20,'Proverbs','OT',25,1,'Ini sila man mga hulubaton ni Salomon, nga ginhuwad sang mga tawo ni Ezequias nga hari sang Juda.'),
(17116,20,'Proverbs','OT',25,2,'Himaya sang Dios ang pagtago sing butang,'),
(17117,20,'Proverbs','OT',25,3,'Subong sang mga langit sa kataason, kag sang duta sa kadalumon,'),
(17118,20,'Proverbs','OT',25,4,'Kuhaa ang buay sa pilak,'),
(17119,20,'Proverbs','OT',25,5,'kuhaa ang malauton sa atubangan sang hari,'),
(17120,20,'Proverbs','OT',25,6,'Dili ka magpakig-agaw sing una sa atubangan sang hari'),
(17121,20,'Proverbs','OT',25,7,'kay maayo pa nga silingan ka, “Saka ka diri,”'),
(17122,20,'Proverbs','OT',25,8,'dili pagdalhon sing dalidali sa corte;'),
(17123,20,'Proverbs','OT',25,9,'Baisi ang imo kasaba upud sa imo isigkatawo,'),
(17124,20,'Proverbs','OT',25,10,'basi pasipalahan ka sang makabati sini,'),
(17125,20,'Proverbs','OT',25,11,'Ang polong nga napamolong sing nagakaigo'),
(17126,20,'Proverbs','OT',25,12,'Subong sang aritos nga bulawan kag puni nga bulawan nga bus-og'),
(17127,20,'Proverbs','OT',25,13,'Subong sang katugnaw sang nieve sa tig-alani'),
(17128,20,'Proverbs','OT',25,14,'Subong sang mga gal-um kag hangin nga wala sing ulan'),
(17129,20,'Proverbs','OT',25,15,'Tungud sa malawig nga pagpaumud nabuyuk ang manugdumala,'),
(17130,20,'Proverbs','OT',25,16,'Nakakita ka bala sing dugus, kaon ka sing tuman sa imo,'),
(17131,20,'Proverbs','OT',25,17,'Magpanalagsa ang imo tiil sa balay sang imo isigkatawo,'),
(17132,20,'Proverbs','OT',25,18,'Ang tawo nga nagasaksi sing dimatuud batok sa iya isigkatawo'),
(17133,20,'Proverbs','OT',25,19,'Ang pagsalig sa tawo nga dimatutum sa tion sang kalisud'),
(17134,20,'Proverbs','OT',25,20,'Subong sang isa nga nagauba sang panapton sa dag-on sang tugnaw'),
(17135,20,'Proverbs','OT',25,21,'Kon gutum ang imo kaaway, hatagi sia sing kalan-on;'),
(17136,20,'Proverbs','OT',25,22,'kay magatumpi ka sing mga baga sa iya olo,#Roma 12:20.'),
(17137,20,'Proverbs','OT',25,23,'Ang amihan nagadala sing ulan;'),
(17138,20,'Proverbs','OT',25,24,'Maayo pa magpuyo sa pamusud sang atop'),
(17139,20,'Proverbs','OT',25,25,'Subong sang mabugnaw nga mga tubig sa kalag nga nauhaw,'),
