(12436,16,'Nehemiah','OT',7,13,'The children of Zattu, eight hundred forty and five.'),
(12437,16,'Nehemiah','OT',7,14,'The children of Zaccai, seven hundred and threescore.'),
(12438,16,'Nehemiah','OT',7,15,'The children of Binnui, six hundred forty and eight. {Binnui: also called, Bani}'),
(12439,16,'Nehemiah','OT',7,16,'The children of Bebai, six hundred twenty and eight.'),
(12440,16,'Nehemiah','OT',7,17,'The children of Azgad, two thousand three hundred twenty and two.'),
(12441,16,'Nehemiah','OT',7,18,'The children of Adonikam, six hundred threescore and seven.'),
(12442,16,'Nehemiah','OT',7,19,'The children of Bigvai, two thousand threescore and seven.'),
