(12570,16,'Nehemiah','OT',10,18,'Hodijah, Hashum, Bezai,'),
(12571,16,'Nehemiah','OT',10,19,'Hariph, Anathoth, Nebai,'),
(12572,16,'Nehemiah','OT',10,20,'Magpiash, Meshullam, Hezir,'),
